def populate_project_locks(apps, schema_editor):
    Event = apps.get_model('surveys', 'ProfileReuseEvent')
    ProjectUsage = apps.get_model('surveys', 'ProfileReuseProjectUsage')
    Attempt = apps.get_model('surveys', 'SurveyAttempt')
    alias = schema_editor.connection.alias
    events = Event.objects.using(alias).select_related('attempt').only(
        'pk', 'integration_id', 'reused_uid', 'attempt_id', 'attempt__survey_id'
    ).order_by('created_at', 'pk')
    for event in events.iterator(chunk_size=1000):
        survey_id = event.attempt.survey_id
        Event.objects.using(alias).filter(pk=event.pk).update(survey_id=survey_id)
        ProjectUsage.objects.using(alias).get_or_create(
            integration_id=event.integration_id,
            survey_id=survey_id,
            reused_uid=event.reused_uid,
            defaults={'first_attempt_id': event.attempt_id},
        )

    # Registration itself counts as the UID's first use on a project.  Seed
    # those locks too so profiles captured before this migration cannot later
    # return to their original survey.
    for field_name in ('prescreener_uid', 'provider_profile_uid'):
        attempts = Attempt.objects.using(alias).exclude(**{field_name: ''}).select_related(
            'survey'
        ).only('pk', 'survey_id', 'survey__integration_id', field_name)
        for attempt in attempts.iterator(chunk_size=1000):
            integration_id = attempt.survey.integration_id
            reused_uid = getattr(attempt, field_name)
            if not integration_id or not reused_uid:
                continue
            ProjectUsage.objects.using(alias).get_or_create(
                integration_id=integration_id,
                survey_id=attempt.survey_id,
                reused_uid=reused_uid,
                defaults={'first_attempt_id': attempt.pk},
            )


